/**
 * 负责阶段顺序数组的保存与替换；输入阶段列表，输出当前顺序的独立浅副本。
 * 构造、登记与读取都复制数组，阶段值保持原顺序，不去重或校验支持范围。
 * 本表只持有配置，不推进阶段、执行 hook 或关闭对局。
 */
import { Phase } from "../model";

/**
 * 阶段顺序注册表：支持按板子动态替换默认 phase 顺序。
 */
export class PhaseRegistry {
  private order: Phase[];

  constructor(order: Phase[] = [Phase.Night, Phase.Day, Phase.Voting]) {
    this.order = [...order];
  }

  /**
   * 返回新数组，调用方修改列表不改写 registry 的当前顺序。
   */
  getOrder(): Phase[] {
    return [...this.order];
  }

  /**
   * 用新副本覆盖全部顺序；传入数组之后的修改不影响保存值。
   */
  registerOrder(order: Phase[]): void {
    this.order = [...order];
  }
}

/**
 * 负责保留胜负系统的既有两参数委托入口；输入原 World 与条件，输出注入评估器的原判定或 null。
 * 规则实现及允许检查点由原评估器拥有，阶段执行和最终封盘仍归管理器；这里不标死或改写结果。
 * 实例只保存原评估器引用，方法读取／调用失败原样传播，不增加缓存、回退规则或配置校验。
 */
import { WinDecision, WinCondition } from "../model";
import { World } from "../world";
import { WinConditionEvaluator } from "../registries/condition_registry";

/**
 * 既有兼容类保留当前公开入口；具体胜负算法已委托原注入评估器，不复制第二份规则。
 */
export class WinConditionSystem {
  private readonly registry: WinConditionEvaluator;

  constructor(registry: WinConditionEvaluator) {
    this.registry = registry;
  }

  /** 保原评估器方法 receiver 和两实参，不额外传检查点；返回与抛错直接交给调用方。 */
  evaluate(world: World, condition: WinCondition): WinDecision | null {
    return this.registry.evaluate(world, condition);
  }
}

/**
 * Public domain boundary for engine, feature and application consumers.
 * Exports existing World storage, component factories, runtime permission ports
 * and domain declarations. The typed component map relates names to original
 * stored objects; exports never serialize handles or replace their owners.
 */
export * from "./model";
export * from "./action_request_context";
export * from "./random";
export { World } from "./world";
export type { ComponentMap, ComponentWrite } from "./component-map";

